// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public {
        address[] memory proposers = new address[](0);
        address[] memory executors = new address[](0);
        c = new TimelockController(0, proposers, executors);
    }
    function testFuzz_property(bytes32 role, address account) public {
        vm.assume(role != c.DEFAULT_ADMIN_ROLE());
        vm.assume(account != address(c));

        bytes32 executorRole = c.EXECUTOR_ROLE();
        bytes32 proposerRole = c.PROPOSER_ROLE();
        bytes32 timelockAdminRole = c.TIMELOCK_ADMIN_ROLE();

        vm.startPrank(address(this));
        c.grantRole(proposerRole, account);
        vm.stopPrank();

        assertTrue(c.hasRole(proposerRole, account));
    }
}
